// Design Name:
// Module Name: tb_ascon_aead_hash
// Project Name:
// Target Devices:
// Tool Versions:
// Description:
// self-checking testbench for the unified core
//
// Vectors come from tb_vectors.svh (generated by
// python_simulation/gen_tb_vectors.py from the NIST-compliant model).
// Each vector is run once; odd/even indices alternate between the two legal
// end-of-stream conventions (hardware pad block vs explicit empty block), and
// every third vector applies random back-pressure on out_ready.
//
// Dependencies: 
//
// Revision:
// Revision 0.01 - File Created
// Additional Comments:
//
//////////////////////////////////////////////////////////////////////////////////


module tb_ascon_aead_hash();
    parameter integer SPLIT_ROUND  = 0;
    parameter integer MERGE_ABSORB = 0;
    parameter integer LEGACY_SCHEDULE = 0;   // 1: previous core (sources_1/v1), cycles = 8R+A / 12R+A
    parameter integer STALL        = 1;   // enable random out_ready stalls

    `include "tb_vectors.svh"

    logic clk = 1'b0;
    logic rst = 1'b1;
    always #5 clk = ~clk;

    logic         start    = 1'b0;
    logic [1:0]   mode     = 2'd0;
    logic [127:0] key      = '0;
    logic [127:0] nonce    = '0;
    logic         in_valid = 1'b0;
    logic [127:0] in_data  = '0;
    logic [4:0]   in_len   = '0;
    logic         in_last  = 1'b0;
    logic         in_ad    = 1'b0;
    wire          in_ready, in_ready_ad, in_ready_msg;
    wire          out_valid;
    wire [127:0]  out_data;
    wire [4:0]    out_len;
    wire          out_last;
    logic         out_ready = 1'b1;
    wire          tag_valid;
    wire [127:0]  tag;
    wire          busy;

    ascon_aead_hash #(.SPLIT_ROUND(SPLIT_ROUND), .MERGE_ABSORB(MERGE_ABSORB)) dut (
        .clk(clk), .rst(rst), .start(start), .mode(mode), .key(key), .nonce(nonce), .busy(busy),
        .in_valid(in_valid), .in_data(in_data), .in_len(in_len), .in_last(in_last), .in_ad(in_ad),
        .in_ready(in_ready), .in_ready_ad(in_ready_ad), .in_ready_msg(in_ready_msg),
        .out_valid(out_valid), .out_data(out_data), .out_len(out_len), .out_last(out_last),
        .out_ready(out_ready), .tag_valid(tag_valid), .tag(tag)
    );

    int errors = 0;
    bit stall_en = 1'b0;

    // random back-pressure, changed only at negedge
    always @(negedge clk) out_ready = (stall_en && STALL != 0) ? ($urandom % 3 != 0) : 1'b1;

    // cycle accounting for throughput measurement
    longint cycle = 0;
    longint first_accept = -1;
    longint last_accept  = -1;
    int     n_accept     = 0;
    always @(posedge clk) begin
        cycle++;
        if (in_valid && in_ready) begin
            if (first_accept < 0) first_accept = cycle;
            last_accept = cycle;
            n_accept++;
        end
    end

    function automatic logic [511:0] mask_bytes(input int len);
        if (len >= 64) return {512{1'b1}};
        return (512'h1 << (8 * len)) - 1;
    endfunction

    // ------------------------------------------------------------------
    // Bus-functional tasks (all driving happens at negedge)
    // ------------------------------------------------------------------
    task automatic do_start(input logic [1:0] m);
        @(negedge clk); mode = m; start = 1'b1;
        @(negedge clk); start = 1'b0;
    endtask

    // Present a block and hold it until accepted.  in_valid stays high so
    // consecutive calls form a back-to-back stream; call end_stream() after.
    task automatic send_block(input logic [127:0] data, input int len, input bit last, input bit ad,
                              output logic [127:0] captured, output bit got_out,
                              input bit expect_out = 1'b0);
        int guard;
        @(negedge clk);
        in_valid = 1'b1; in_data = data; in_len = len[4:0]; in_last = last; in_ad = ad;
        #1;
        while (!in_ready) begin @(negedge clk); #1; end
        got_out  = out_valid & out_ready;     // v1: output offered in the accept cycle
        captured = out_data;
        @(posedge clk);                       // block accepted here
        if (expect_out && !got_out) begin     // v2: output offered after the accept
            guard = 0;
            forever begin
                @(negedge clk);
                in_valid = 1'b0;              // drive only at negedge (no posedge race)
                #1;
                if (out_valid && out_ready) begin
                    got_out = 1'b1; captured = out_data;
                    @(posedge clk);
                    break;
                end
                if (++guard > 64) break;
            end
        end
    endtask

    task automatic end_stream();
        @(negedge clk); in_valid = 1'b0; in_last = 1'b0; in_ad = 1'b0; in_len = '0;
    endtask

    task automatic recv_block(output logic [127:0] data, output int len, output bit last);
        forever begin
            @(negedge clk); #1;
            if (out_valid && out_ready) begin
                data = out_data; len = out_len; last = out_last;
                @(posedge clk);
                return;
            end
        end
    endtask

    // ------------------------------------------------------------------
    // Ascon-Hash256
    // ------------------------------------------------------------------
    task automatic run_hash(input int idx, input bit explicit_pad);
        logic [127:0] cap, d;
        logic [255:0] digest;
        bit got, lst, last;
        int len, off, blen, l;
        len = hash_len[idx];
        do_start(2'd0);
        if (len == 0) begin
            send_block('0, 0, 1'b1, 1'b0, cap, got);
        end else begin
            off = 0;
            while (off < len) begin
                blen = (len - off > 8) ? 8 : (len - off);
                last = (off + blen == len);
                if (last && blen == 8 && explicit_pad) begin
                    send_block({64'd0, hash_msg[idx][8*off +: 64]}, 8, 1'b0, 1'b0, cap, got);
                    send_block('0, 0, 1'b1, 1'b0, cap, got);
                end else begin
                    send_block({64'd0, hash_msg[idx][8*off +: 64]}, blen, last, 1'b0, cap, got);
                end
                off += blen;
            end
        end
        end_stream();
        digest = '0;
        for (int k = 0; k < 4; k++) begin
            recv_block(d, l, lst);
            digest[64*k +: 64] = d[63:0];
            if (l != 8) begin $display("HASH %0d: squeeze %0d has len %0d", idx, k, l); errors++; end
            if (lst != (k == 3)) begin $display("HASH %0d: squeeze %0d last=%0d", idx, k, lst); errors++; end
        end
        if (digest !== hash_md[idx]) begin
            $display("HASH %0d FAIL (len %0d)\n  exp %h\n  got %h", idx, len, hash_md[idx], digest);
            errors++;
        end
    endtask

    // ------------------------------------------------------------------
    // Ascon-AEAD128 encrypt / decrypt
    // ------------------------------------------------------------------
    task automatic run_aead(input int idx, input bit decrypt, input bit explicit_pad);
        logic [127:0] cap;
        logic [511:0] src, exp, got_data, m;
        bit got, last;
        int alen, plen, off, blen;
        alen = aead_adlen[idx];
        plen = aead_ptlen[idx];
        src  = decrypt ? aead_ct[idx] : aead_pt[idx];
        exp  = decrypt ? aead_pt[idx] : aead_ct[idx];
        key   = aead_key[idx];
        nonce = aead_nonce[idx];
        do_start(decrypt ? 2'd2 : 2'd1);

        off = 0;
        while (off < alen) begin
            blen = (alen - off > 16) ? 16 : (alen - off);
            last = (off + blen == alen);
            if (last && blen == 16 && explicit_pad) begin
                send_block(aead_ad[idx][8*off +: 128], 16, 1'b0, 1'b1, cap, got);
                send_block('0, 0, 1'b1, 1'b1, cap, got);
            end else begin
                send_block(aead_ad[idx][8*off +: 128], blen, last, 1'b1, cap, got);
            end
            off += blen;
        end

        got_data = '0;
        if (plen == 0) begin
            send_block('0, 0, 1'b1, 1'b0, cap, got, 1'b1);
            if (!got) begin $display("AEAD %0d: no output handshake on empty block", idx); errors++; end
        end else begin
            off = 0;
            while (off < plen) begin
                blen = (plen - off > 16) ? 16 : (plen - off);
                last = (off + blen == plen);
                if (last && blen == 16 && explicit_pad) begin
                    send_block(src[8*off +: 128], 16, 1'b0, 1'b0, cap, got, 1'b1);
                    got_data[8*off +: 128] = cap;
                    if (!got) begin $display("AEAD %0d: missing output at byte %0d", idx, off); errors++; end
                    send_block('0, 0, 1'b1, 1'b0, cap, got, 1'b1);   // explicit empty last block
                end else begin
                    send_block(src[8*off +: 128], blen, last, 1'b0, cap, got, 1'b1);
                    got_data[8*off +: 128] = cap;
                    if (!got) begin $display("AEAD %0d: missing output at byte %0d", idx, off); errors++; end
                end
                off += blen;
            end
        end
        end_stream();

        m = mask_bytes(plen);
        if ((got_data & m) !== (exp & m)) begin
            $display("AEAD %0d %s FAIL data (ad %0d, msg %0d)\n  exp %h\n  got %h", idx,
                     decrypt ? "DEC" : "ENC", alen, plen, exp & m, got_data & m);
            errors++;
        end
        while (!tag_valid) @(negedge clk);
        if (tag !== aead_tag[idx]) begin
            $display("AEAD %0d %s FAIL tag (ad %0d, msg %0d)\n  exp %h\n  got %h", idx,
                     decrypt ? "DEC" : "ENC", alen, plen, aead_tag[idx], tag);
            errors++;
        end
    endtask

    // ------------------------------------------------------------------
    // Steady-state cycles per block (vector 0 is 64 bytes in both sets)
    // ------------------------------------------------------------------
    task automatic measure(input bit aead_mode, input int expected);
        real cpb;
        stall_en = 1'b0;
        first_accept = -1; n_accept = 0;
        if (aead_mode) run_aead(0, 1'b0, 1'b0); else run_hash(0, 1'b0);
        cpb = real'(last_accept - first_accept) / real'(n_accept - 1);
        $display("%s streaming: %0d blocks, %.2f cycles/block (expected %0d)",
                 aead_mode ? "AEAD128" : "HASH256", n_accept, cpb, expected);
        if (cpb != expected) begin $display("  cycle budget violated"); errors++; end
    endtask

    initial begin
        load_vectors();
        repeat (3) @(negedge clk);
        rst = 1'b0;
        @(negedge clk);

        for (int i = 0; i < N_HASH; i++) begin
            stall_en = (i % 3 == 2);
            run_hash(i, i % 2 == 1);
        end
        for (int i = 0; i < N_AEAD; i++) begin
            stall_en = (i % 3 == 2);
            run_aead(i, 1'b0, i % 2 == 1);
        end
        for (int i = 0; i < N_AEAD; i++) begin
            stall_en = (i % 3 == 2);
            run_aead(i, 1'b1, i % 2 == 0);
        end
        stall_en = 1'b0;

        // rounds x (1 or 2 cycles) + one absorb cycle unless merged into the first round
        // current core: 12 / 8 cycles per block regardless of the parameters
        measure(1'b0, LEGACY_SCHEDULE ? 12 * (SPLIT_ROUND ? 2 : 1) + (MERGE_ABSORB ? 0 : 1) : 12);
        measure(1'b1, LEGACY_SCHEDULE ?  8 * (SPLIT_ROUND ? 2 : 1) + (MERGE_ABSORB ? 0 : 1) : 8);

        if (errors == 0)
            $display("ALL TESTS PASSED (SPLIT_ROUND=%0d MERGE_ABSORB=%0d): %0d hash, %0d encrypt, %0d decrypt vectors",
                     SPLIT_ROUND, MERGE_ABSORB, N_HASH, N_AEAD, N_AEAD);
        else
            $display("FAILED: %0d errors (SPLIT_ROUND=%0d MERGE_ABSORB=%0d)", errors, SPLIT_ROUND, MERGE_ABSORB);
        $finish;
    end
endmodule
